const GROQ_KEY = import.meta.env.VITE_GROQ_API_KEY as string | undefined;
const HIBP_KEY = import.meta.env.VITE_HIBP_API_KEY as string | undefined;

interface OrgEntry {
  id: string;
  name: string;
  domain: string;
  addedAt: string;
  lastChecked: string | null;
  status: "monitoring" | "alert" | "clean" | "checking";
  riskScore: number;
  findings: OrgFinding[];
}

interface OrgFinding {
  source: string;
  type: "breach" | "mention" | "leak" | "darkweb" | "threat_feed";
  title: string;
  detail: string;
  fullContent?: string;
  url?: string;
  category?: string;
  affectedCount?: number;
  dataClasses?: string[];
  date: string;
  severity: "critical" | "high" | "medium" | "low";
}

// ── HIBP domain breach check (public, no key needed) ─────────────────────────
async function checkHIBP(domain: string): Promise<OrgFinding[]> {
  try {
    const ctrl = new AbortController();
    setTimeout(() => ctrl.abort(), 10000);
    const res = await fetch(`https://haveibeenpwned.com/api/v3/breaches?domain=${encodeURIComponent(domain)}`, {
      signal: ctrl.signal,
      headers: HIBP_KEY ? { "hibp-api-key": HIBP_KEY } : {},
    });
    if (!res.ok) return [];
    const breaches = await res.json();
    if (!Array.isArray(breaches)) return [];
    return breaches.slice(0, 10).map((b: any) => {
      const count = b.PwnCount || 0;
      const classes = b.DataClasses || [];
      return {
        source: "HaveIBeenPwned",
        type: "breach" as const,
        title: `${b.Title || b.Name} Data Breach`,
        detail: `${count.toLocaleString()} accounts exposed. Data: ${classes.slice(0, 4).join(", ")}`,
        fullContent: [
          `Breach Name: ${b.Name || b.Title}`,
          `Domain: ${b.Domain || "—"}`,
          `Breach Date: ${b.BreachDate || "Unknown"}`,
          `Date Added to HIBP: ${b.AddedDate || "Unknown"}`,
          `Pwned Accounts: ${count.toLocaleString()}`,
          `Data Classes Exposed: ${classes.join(", ") || "Unknown"}`,
          `Verified: ${b.IsVerified ? "Yes" : "No"}`,
          `Fabricated: ${b.IsFabricated ? "Yes" : "No"}`,
          `Sensitive: ${b.IsSensitive ? "Yes" : "No"}`,
          `Description: ${(b.Description || "").replace(/<[^>]+>/g, " ").trim() || "No description available."}`,
        ].join("\n"),
        url: `https://haveibeenpwned.com/PwnedWebsites#${b.Name}`,
        affectedCount: count,
        dataClasses: classes,
        date: b.BreachDate || b.AddedDate || "",
        severity: count > 1000000 ? "critical" : count > 100000 ? "high" : "medium" as any,
      };
    });
  } catch { return []; }
}

// ── Internal threat feed search — STRICT word-boundary match ──────────────
// ILIKE %term% matches "acme" inside "acmesoft", "acmen", "lacme", etc.,
// causing huge false-positive piles. We post-filter with a real word-boundary
// regex so only items that genuinely mention the org or domain survive.
async function checkInternalFeed(orgName: string, domain?: string): Promise<OrgFinding[]> {
  try {
    const orgClean = (orgName || "").trim().toLowerCase();
    const domClean = (domain  || "").trim().toLowerCase();
    if (!orgClean && !domClean) return [];

    // Use exact string match in DB query (ilike) then word-boundary regex
    // client-side. The DB query is just a cheap pre-filter; correctness
    // comes from the regex.
    const orParts: string[] = [];
    for (const v of [orgClean, domClean].filter(Boolean)) {
      orParts.push(`title.ilike.%${v}%`);
      orParts.push(`excerpt.ilike.%${v}%`);
      orParts.push(`ai_summary.ilike.%${v}%`);
    }

    let res = await supabase
      .from("threat_items")
      .select("id,title,excerpt,ai_summary,severity,source_name,published_at,link,category,iocs")
      .or(orParts.join(","))
      .order("published_at", { ascending: false })
      .limit(80);

    if (res.error?.message?.includes("ai_summary")) {
      const fbOrParts = [orgClean, domClean].filter(Boolean).flatMap(v => [`title.ilike.%${v}%`, `excerpt.ilike.%${v}%`]);
      res = await supabase
        .from("threat_items")
        .select("id,title,excerpt,severity,source_name,published_at,link,category,iocs")
        .or(fbOrParts.join(","))
        .order("published_at", { ascending: false })
        .limit(80);
    }

    // Build strict regexes — word boundaries, escape special chars
    function esc(s: string)  { return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); }
    const orgRe   = orgClean ? new RegExp(`\\b${esc(orgClean)}\\b`, "i") : null;
    const domBase = domClean ? domClean.replace(/^www\./, "") : "";
    const domRe   = domBase
      ? new RegExp(`(^|[^a-z0-9])${esc(domBase)}(\\W|$)`, "i")  // exact domain match (no substring poisoning)
      : null;

    const LEAK_KEYWORDS = ["confidential", "leaked", "leak", "exposed", "breach", "stolen", "ransomware", "data dump", "internal documents", "private credential", "sensitive data"];
    const findings: OrgFinding[] = [];

    for (const item of (res.data || []) as any[]) {
      const blob = `${item.title || ""} ${item.excerpt || ""} ${item.ai_summary || ""}`;
      // Must hit org OR domain with a word boundary — substring matches are
      // false-positive land (e.g. "okta" hitting "tokota").
      const orgHit = orgRe ? orgRe.test(blob) : false;
      const domHit = domRe ? domRe.test(blob) : false;
      if (!orgHit && !domHit) continue;

      const lower = blob.toLowerCase();
      const isLeak = LEAK_KEYWORDS.some(kw => lower.includes(kw));

      findings.push({
        source: item.source_name || "Internal Feed",
        type: isLeak ? ("leak" as const) : ("threat_feed" as const),
        title: item.title,
        detail: (item.excerpt || item.ai_summary || "").slice(0, 250),
        fullContent: item.ai_summary || item.excerpt || "No additional content available.",
        url: item.link || undefined,
        category: item.category || undefined,
        date: item.published_at || "",
        severity: (isLeak && item.severity === "low" ? "high" : (item.severity || "medium")) as any,
      });
      if (findings.length >= 30) break;
    }
    return findings;
  } catch (e) {
    console.error("checkInternalFeed error:", e);
    return [];
  }
}

// ── Hudson Rock domain check ──────────────────────────────────────────────────
async function checkHudsonRock(domain: string): Promise<OrgFinding[]> {
  try {
    const proxies = [
      `https://corsproxy.io/?`,
      `https://api.allorigins.win/raw?url=`,
    ];
    for (const proxy of proxies) {
      try {
        const url = `https://cavalier.hudsonrock.com/api/json/v2/osint-tools/search-by-domain?domain=${encodeURIComponent(domain)}`;
        const ctrl = new AbortController();
        setTimeout(() => ctrl.abort(), 8000);
        const res = await fetch(`${proxy}${encodeURIComponent(url)}`, { signal: ctrl.signal });
        if (!res.ok) continue;
        const d = await res.json();
        const employees = d?.employees || [];
        const computers = d?.stealers || d?.total || 0;
        if (employees.length === 0 && !computers) return [];
        const sampleEmployees = employees.slice(0, 5).map((e: any) =>
          `• ${e.username || e.email || "Unknown"} (${e.computer_name || "Unknown device"}, ${e.date_compromised ? new Date(e.date_compromised).toLocaleDateString() : "Unknown date"})`
        ).join("\n");
        return [{
          source: "Hudson Rock Cavalier",
          type: "leak" as const,
          title: `${domain} — Infostealer Compromise`,
          detail: `${employees.length} compromised employee accounts, ${typeof computers === "number" ? computers : employees.length} stealer log entries found. Credentials actively exfiltrated.`,
          fullContent: [
            `Domain: ${domain}`,
            `Compromised Employees: ${employees.length}`,
            `Stealer Log Entries: ${typeof computers === "number" ? computers : employees.length}`,
            `Threat Level: Credentials have been actively exfiltrated via infostealer malware.`,
            employees.length > 0 ? `\nSample Compromised Accounts:\n${sampleEmployees}` : "",
            `\nSource: Hudson Rock Cavalier OSINT Platform`,
            `Note: Infostealer logs typically include saved browser credentials, cookies, autofill data, and crypto wallets.`,
          ].filter(Boolean).join("\n"),
          date: new Date().toISOString(),
          severity: employees.length > 10 ? "critical" : employees.length > 3 ? "high" : "medium" as any,
        }];
      } catch { continue; }
    }
    return [];
  } catch { return []; }
}

// ── AI correlation summary ────────────────────────────────────────────────────
// ── Live attack surface — Shodan + GreyNoise + URLhaus + ThreatFox + OTX ──
// Resolves the domain to an IP (via Cloudflare DNS-over-HTTPS, no CORS issues)
// then queries every public threat-intel source we can reach. Each source
// produces one OrgFinding so the analyst sees per-source attribution.
async function checkLiveAttackSurface(domain: string): Promise<OrgFinding[]> {
  if (!domain) return [];
  const out: OrgFinding[] = [];
  const dom = domain.trim().toLowerCase().replace(/^www\./, "");

  // 1. Resolve A record via Cloudflare DNS-over-HTTPS (CORS-safe)
  let ip = "";
  try {
    const r = await fetch(`https://cloudflare-dns.com/dns-query?name=${encodeURIComponent(dom)}&type=A`, {
      headers: { Accept: "application/dns-json" },
      signal:  AbortSignal.timeout(8000),
    });
    if (r.ok) {
      const j = await r.json();
      const a = (j?.Answer ?? []).find((x: any) => x.type === 1);
      if (a?.data) ip = String(a.data).trim();
    }
  } catch { /* DNS may fail, continue with domain-only checks */ }

  // 2. Shodan InternetDB — open ports, exposed vulns, hostnames
  if (ip) {
    try {
      const r = await fetch(`https://internetdb.shodan.io/${encodeURIComponent(ip)}`, { signal: AbortSignal.timeout(10000) });
      if (r.ok) {
        const d = await r.json();
        const ports = (d.ports ?? []) as number[];
        const vulns = (d.vulns ?? []) as string[];
        if (ports.length > 0 || vulns.length > 0) {
          out.push({
            source: "Shodan InternetDB",
            type: "exposure" as any,
            title: `${dom} (${ip}) — internet-exposed surface`,
            detail: `${ports.length} open ports${vulns.length ? `, ${vulns.length} known vulns` : ""}.`,
            fullContent: [
              `Resolved IP: ${ip}`,
              `Open ports: ${ports.join(", ") || "none reported"}`,
              vulns.length ? `Known CVEs on services: ${vulns.slice(0, 10).join(", ")}` : "",
              (d.cpes ?? []).length ? `Software fingerprint: ${d.cpes.slice(0, 5).join(" · ")}` : "",
              (d.tags ?? []).length ? `Shodan tags: ${d.tags.join(", ")}` : "",
            ].filter(Boolean).join("\n"),
            url: `https://www.shodan.io/host/${ip}`,
            date: new Date().toISOString(),
            severity: vulns.length > 0 ? "high" : ports.length > 5 ? "medium" : "low",
          });
        }
      }
    } catch { /* ignore */ }

    // 3. GreyNoise — is this IP itself a known scanner, or seen scanning others?
    try {
      const r = await fetch(`https://api.greynoise.io/v3/community/${encodeURIComponent(ip)}`, { signal: AbortSignal.timeout(8000) });
      if (r.ok) {
        const d = await r.json();
        if (d?.classification && d.classification !== "unknown") {
          out.push({
            source: "GreyNoise",
            type: "attacker" as any,
            title: `${ip} flagged ${d.classification}${d.name ? ` (${d.name})` : ""}`,
            detail: d.classification === "malicious"
              ? `Active mass-scanner / brute-forcer traffic seen from this IP. Last seen ${d.last_seen ?? "recently"}.`
              : `Benign internet noise — typically a security scanner.`,
            fullContent: JSON.stringify(d, null, 2),
            url: d.link ?? `https://viz.greynoise.io/ip/${ip}`,
            date: new Date().toISOString(),
            severity: d.classification === "malicious" ? "high" : "low",
          });
        }
      }
    } catch { /* ignore */ }
  }

  // 4. URLhaus — has the domain been used to host malware?
  try {
    const r = await fetch("https://urlhaus-api.abuse.ch/v1/host/", {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({ host: dom }).toString(),
      signal: AbortSignal.timeout(10000),
    });
    if (r.ok) {
      const d = await r.json();
      if (d?.query_status === "ok" && (d.url_count ?? 0) > 0) {
        const samples = (d.urls ?? []).slice(0, 5).map((u: any) =>
          `• ${u.url_status === "online" ? "🔴 LIVE" : "○ offline"} ${u.threat ?? ""} — ${u.url?.slice(0, 90)}`,
        ).join("\n");
        out.push({
          source: "URLhaus (abuse.ch)",
          type: "leak" as const,
          title: `${dom} — ${d.url_count} malicious URL${d.url_count === 1 ? "" : "s"} on this domain`,
          detail: `First-seen ${d.firstseen}. Used for malware distribution.`,
          fullContent: [
            `Total malicious URLs: ${d.url_count}`,
            `First seen: ${d.firstseen}`,
            d.blacklists ? `Blacklists: ${JSON.stringify(d.blacklists)}` : "",
            samples ? `\nRecent malicious URLs:\n${samples}` : "",
          ].filter(Boolean).join("\n"),
          url: `https://urlhaus.abuse.ch/host/${dom}/`,
          date: new Date().toISOString(),
          severity: "critical",
        });
      }
    }
  } catch { /* ignore */ }

  // 5. ThreatFox — IOC records mentioning the domain
  try {
    const r = await fetch("https://threatfox-api.abuse.ch/api/v1/", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ query: "search_ioc", search_term: dom }),
      signal: AbortSignal.timeout(10000),
    });
    if (r.ok) {
      const d = await r.json();
      const recs = Array.isArray(d?.data) ? d.data : [];
      if (recs.length > 0) {
        out.push({
          source: "ThreatFox (abuse.ch)",
          type: "attacker" as any,
          title: `${dom} — ${recs.length} active IOC record${recs.length === 1 ? "" : "s"}`,
          detail: `Tied to malware: ${[...new Set(recs.map((r: any) => r.malware_printable ?? r.malware).filter(Boolean))].slice(0, 3).join(", ")}.`,
          fullContent: recs.slice(0, 6).map((r: any) => `• ${r.malware_printable ?? r.malware ?? "?"} — ${r.threat_type ?? "active"} — ${r.last_seen ?? ""}`).join("\n"),
          url: "https://threatfox.abuse.ch/",
          date: new Date().toISOString(),
          severity: "high",
        });
      }
    }
  } catch { /* ignore */ }

  // 6. AlienVault OTX — community pulses on the domain
  try {
    const r = await fetch(`https://otx.alienvault.com/api/v1/indicators/domain/${encodeURIComponent(dom)}/general`, { signal: AbortSignal.timeout(10000) });
    if (r.ok) {
      const d = await r.json();
      const count = d?.pulse_info?.count ?? 0;
      if (count > 0) {
        const pulses = (d.pulse_info?.pulses ?? []).slice(0, 5);
        out.push({
          source: "AlienVault OTX",
          type: "attacker" as any,
          title: `${dom} appears in ${count} community threat pulse${count === 1 ? "" : "s"}`,
          detail: pulses[0] ? `e.g. "${String(pulses[0].name).slice(0, 100)}"` : "",
          fullContent: pulses.map((p: any) =>
            `• ${p.name}\n  Actor: ${p.adversary ?? "unknown"} · Tags: ${(p.tags ?? []).slice(0, 6).join(", ")}`,
          ).join("\n\n"),
          url: `https://otx.alienvault.com/indicator/domain/${dom}`,
          date: new Date().toISOString(),
          severity: count >= 5 ? "high" : "medium",
        });
      }
    }
  } catch { /* ignore */ }

  // 7. Ransomware leak-site mentions (ransomware.live victim search)
  try {
    const r = await fetch(`https://api.ransomware.live/v2/searchvictims/${encodeURIComponent(dom)}`, { signal: AbortSignal.timeout(10000) });
    if (r.ok) {
      const d = await r.json();
      const arr = Array.isArray(d) ? d : Array.isArray(d?.victims) ? d.victims : [];
      if (arr.length > 0) {
        out.push({
          source: "ransomware.live",
          type: "leak" as const,
          title: `${dom} listed on ${arr.length} ransomware leak site${arr.length === 1 ? "" : "s"}`,
          detail: arr.slice(0, 3).map((v: any) => `${v.group_name ?? v.group}: ${v.victim ?? v.name}`).join(" · "),
          fullContent: arr.slice(0, 8).map((v: any) => `• ${v.group_name ?? v.group} — ${v.victim ?? v.name ?? "?"} (${v.discovered ?? v.date ?? ""})`).join("\n"),
          url: `https://www.ransomware.live/search?q=${encodeURIComponent(dom)}`,
          date: new Date().toISOString(),
          severity: "critical",
        });
      }
    }
  } catch { /* ignore */ }

  return out;
}

// ── Real-time news search ──────────────────────────────────────────────────
// Catches anything the strict internal-feed regex missed — recent articles,
// supply-chain attacks, breach disclosures, etc. mentioning the org or domain.
// Uses Google News RSS via the Supabase CORS proxy (no API key needed).
async function checkNewsMentions(orgName: string, domain: string): Promise<OrgFinding[]> {
  const out: OrgFinding[] = [];
  const queries = [
    `"${orgName}" (breach OR ransomware OR attack OR vulnerability OR leak)`,
    domain ? `"${domain}" (breach OR ransomware OR attack OR exposed)` : "",
  ].filter(Boolean);

  for (const q of queries) {
    const enc = encodeURIComponent(q);
    const url = `https://news.google.com/rss/search?q=${enc}&hl=en-US&gl=US&ceid=US:en`;
    // Try public CORS proxies first, fall back to Supabase
    const candidates = [
      `https://corsproxy.io/?${encodeURIComponent(url)}`,
      `https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`,
      `https://api.codetabs.com/v1/proxy?quest=${encodeURIComponent(url)}`,
    ];
    let xml = "";
    for (const proxyUrl of candidates) {
      try {
        const r = await fetch(proxyUrl, { signal: AbortSignal.timeout(10000) });
        if (!r.ok) continue;
        const txt = await r.text();
        if (txt.includes("<item")) { xml = txt; break; }
      } catch { /* try next */ }
    }
    if (!xml) continue;

    // Parse RSS items
    const itemRe = /<item[\s\S]*?<\/item>/gi;
    let m: RegExpExecArray | null;
    let count = 0;
    while ((m = itemRe.exec(xml)) !== null && count < 6) {
      const block = m[0];
      const rawTitle = (block.match(/<title[^>]*><!\[CDATA\[([\s\S]*?)\]\]><\/title>/i)?.[1]
                     || block.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1] || "")
                        .replace(/<[^>]+>/g, "").trim();
      let link = (block.match(/<link>([\s\S]*?)<\/link>/i)?.[1] || "").trim();
      if (link.includes("news.google.com") && link.includes("url=")) {
        const u = link.match(/url=([^&]+)/); if (u) link = decodeURIComponent(u[1]);
      }
      const desc = (block.match(/<description[^>]*>([\s\S]*?)<\/description>/i)?.[1] || "")
                     .replace(/<[^>]+>/g, "").replace(/&[a-z]+;/gi, " ").trim();
      const pub  = (block.match(/<pubDate>([\s\S]*?)<\/pubDate>/i)?.[1] || "").trim();
      if (!rawTitle || !link) continue;

      // Severity heuristic from keywords in the title
      const t = rawTitle.toLowerCase();
      const sev: "critical" | "high" | "medium" | "low" =
        /ransomware|data leak|exposed|breach|exploit|0-?day|zero-?day|critical/.test(t) ? "high" :
        /attack|vulnerability|patch|cve/.test(t)                                      ? "medium" :
        "low";
      const isLeak = /breach|leak|exposed|stolen|ransom|dump/.test(t);

      out.push({
        source: "Google News (live)",
        type: isLeak ? ("leak" as const) : ("threat_feed" as const),
        title: rawTitle,
        detail: desc.slice(0, 220),
        fullContent: `Query: ${q}\n\n${desc}`,
        url: link,
        date: pub ? new Date(pub).toISOString() : new Date().toISOString(),
        severity: sev,
      });
      count++;
    }
  }

  // Dedupe by URL — both queries can return overlapping articles
  const seen = new Set<string>();
  return out.filter((f) => {
    if (!f.url || seen.has(f.url)) return false;
    seen.add(f.url);
    return true;
  });
}

async function generateOrgRiskSummary(org: string, findings: OrgFinding[]): Promise<string> {
  if (!GROQ_KEY || findings.length === 0) {
    const critCount = findings.filter(f => f.severity === "critical").length;
    const highCount = findings.filter(f => f.severity === "high").length;
    if (findings.length === 0) return `No active threats found for ${org} at this time. Continue monitoring.`;
    return `${org} has ${findings.length} findings: ${critCount} critical, ${highCount} high severity. Sources: ${[...new Set(findings.map(f => f.source))].join(", ")}. Immediate investigation recommended for critical findings.`;
  }

  const findingsSummary = findings.slice(0, 8).map(f =>
    `[${f.severity.toUpperCase()}] ${f.source}: ${f.title} — ${f.detail}`
  ).join("\n");

  try {
    const ctrl = new AbortController();
    setTimeout(() => ctrl.abort(), 20000);
    const res = await fetch("https://api.groq.com/openai/v1/chat/completions", {
      method: "POST", signal: ctrl.signal,
      headers: { "Content-Type": "application/json", "Authorization": `Bearer ${GROQ_KEY}` },
      body: JSON.stringify({
        model: "llama-3.3-70b-versatile",
        messages: [{ role: "user", content: `You are a threat intelligence analyst. Summarize the cyber risk for "${org}" based on these findings in 3-4 sentences. Be specific. Focus on business impact and what the security team should do immediately.\n\nFindings:\n${findingsSummary}` }],
        temperature: 0.3, max_tokens: 400,
      }),
    });
    if (!res.ok) throw new Error();
    const d = await res.json();
    return d.choices?.[0]?.message?.content?.trim() || "";
  } catch {
    const critCount = findings.filter(f => f.severity === "critical").length;
    return `${org} has ${findings.length} intelligence findings across ${[...new Set(findings.map(f => f.source))].length} sources. ${critCount > 0 ? `${critCount} CRITICAL findings require immediate response.` : "No critical findings, but monitoring continues."}`;
  }
}

// ── Risk score calculator ─────────────────────────────────────────────────────
function calcRisk(findings: OrgFinding[]): number {
  if (findings.length === 0) return 0;
  const weights = { critical: 35, high: 20, medium: 10, low: 5 };
  const raw = findings.reduce((s, f) => s + (weights[f.severity] || 5), 0);
  return Math.min(100, raw);
}

// ── Copy button ───────────────────────────────────────────────────────────────
function CopyBtn({ value }: { value: string }) {
  const [c, setC] = useState(false);
  return (
    <button onClick={() => { navigator.clipboard.writeText(value); setC(true); setTimeout(() => setC(false), 1500); }}
      className="text-muted-foreground hover:text-foreground transition-colors">
      {c ? <Check className="h-3 w-3 text-green-400" /> : <Copy className="h-3 w-3" />}
    </button>
  );
}

const SEV_BADGE: Record<string, string> = {
  critical: "bg-red-500/15 text-red-400 border-red-500/40",
  high:     "bg-orange-400/15 text-orange-400 border-orange-400/40",
  medium:   "bg-blue-400/15 text-blue-400 border-blue-400/40",
  low:      "bg-green-500/15 text-green-400 border-green-500/40",
};

const TYPE_ICON: Record<string, React.ElementType> = {
  breach: AlertOctagon, mention: Search, leak: Database, threat_feed: TrendingUp, darkweb: Globe,
};

// ── Download helpers ──────────────────────────────────────────────────────────
function downloadJSON(org: OrgEntry) {
  const payload = {
    organization: org.name,
    domain: org.domain,
    riskScore: org.riskScore,
    lastChecked: org.lastChecked,
    totalFindings: org.findings.length,
    findings: org.findings.map(f => ({
      title: f.title,
      source: f.source,
      type: f.type,
      severity: f.severity,
      date: f.date,
      category: f.category || null,
      affectedCount: f.affectedCount || null,
      dataClasses: f.dataClasses || null,
      detail: f.detail,
      fullContent: f.fullContent || f.detail,
      url: f.url || null,
    })),
  };
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = `${org.name.replace(/\s+/g, "_")}_threat_report_${new Date().toISOString().slice(0, 10)}.json`;
  a.click();
  URL.revokeObjectURL(a.href);
}

function downloadCSV(org: OrgEntry) {
  const headers = ["Title", "Source", "Type", "Severity", "Date", "Category", "Affected Count", "Data Classes", "Detail", "Full Content", "URL"];
  const rows = org.findings.map(f => [
    f.title, f.source, f.type, f.severity, f.date,
    f.category || "", String(f.affectedCount || ""),
    (f.dataClasses || []).join("; "),
    f.detail, f.fullContent || f.detail, f.url || "",
  ].map(v => `"${String(v).replace(/"/g, '""')}"`));
  const csv = [headers.join(","), ...rows.map(r => r.join(","))].join("\n");
  const blob = new Blob([csv], { type: "text/csv" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = `${org.name.replace(/\s+/g, "_")}_threat_report_${new Date().toISOString().slice(0, 10)}.csv`;
  a.click();
  URL.revokeObjectURL(a.href);
}

// ── Expandable finding card ───────────────────────────────────────────────────
function FindingCard({ f }: { f: OrgFinding }) {
  const [expanded, setExpanded] = useState(false);
  const TypeIcon = TYPE_ICON[f.type] || Shield;
  const hasMore = !!(f.fullContent && f.fullContent !== f.detail);

  return (
    <div className={`rounded-lg border p-3 ${SEV_BADGE[f.severity].replace("text-", "border-").split(" ")[0]} bg-muted/10`}>
      <div className="flex items-start gap-2">
        <TypeIcon className={`h-4 w-4 shrink-0 mt-0.5 ${SEV_BADGE[f.severity].split(" ")[1]}`} />
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap mb-1">
            <span className="text-sm font-semibold">{f.title}</span>
            <Badge variant="outline" className={`text-[9px] ${SEV_BADGE[f.severity]}`}>{f.severity.toUpperCase()}</Badge>
            {f.category && <Badge variant="outline" className="text-[9px] border-border/50 text-muted-foreground">{f.category}</Badge>}
            <span className="text-[10px] text-muted-foreground ml-auto">{f.source}</span>
          </div>

          {/* Summary detail always shown */}
          <p className="text-xs text-foreground/75 leading-relaxed">{f.detail}</p>

          {/* Expanded full content */}
          {expanded && f.fullContent && (
            <div className="mt-2 pt-2 border-t border-border/30 space-y-1.5">
              {f.dataClasses && f.dataClasses.length > 0 && (
                <div>
                  <span className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wide">Data Classes Exposed</span>
                  <div className="flex flex-wrap gap-1 mt-1">
                    {f.dataClasses.map((dc, i) => (
                      <Badge key={i} variant="outline" className="text-[9px] border-orange-400/40 text-orange-300">{dc}</Badge>
                    ))}
                  </div>
                </div>
              )}
              {f.affectedCount && f.affectedCount > 0 && (
                <div className="text-[11px] text-muted-foreground">
                  <span className="font-semibold text-foreground/80">Affected Accounts:</span> {f.affectedCount.toLocaleString()}
                </div>
              )}
              <pre className="text-[11px] text-foreground/80 leading-relaxed whitespace-pre-wrap font-mono bg-muted/20 rounded p-2 mt-1 max-h-48 overflow-y-auto">
                {f.fullContent}
              </pre>
              {f.url && (
                <a href={f.url} target="_blank" rel="noopener noreferrer"
                  className="inline-flex items-center gap-1 text-[10px] text-primary hover:underline mt-1">
                  <ExternalLink className="h-3 w-3" /> View source
                </a>
              )}
            </div>
          )}

          <div className="flex items-center justify-between mt-1.5">
            <div className="text-[10px] text-muted-foreground">
              {f.date ? new Date(f.date).toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" }) : ""}
            </div>
            {hasMore && (
              <button onClick={() => setExpanded(e => !e)}
                className="flex items-center gap-0.5 text-[10px] text-primary hover:text-primary/80 transition-colors font-medium">
                {expanded ? <><ChevronUp className="h-3 w-3" />Show less</> : <><ChevronDown className="h-3 w-3" />Show full details</>}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

// ── Main component ─────────────────────────────────────────────────────────────
export default function OrgMonitor() {
  const { toast } = useToast();
  const [orgs, setOrgs] = useState<OrgEntry[]>(() => {
    try { return JSON.parse(localStorage.getItem("org_monitor_list") || "[]"); } catch { return []; }
  });
  const [newOrg, setNewOrg] = useState("");
  const [newDomain, setNewDomain] = useState("");
  const [selected, setSelected] = useState<string | null>(null);
  const [aiSummary, setAiSummary] = useState<Record<string, string>>({});
  const [summaryLoading, setSummaryLoading] = useState<Record<string, boolean>>({});

  const save = (list: OrgEntry[]) => {
    setOrgs(list);
    localStorage.setItem("org_monitor_list", JSON.stringify(list));
  };

  const addOrg = () => {
    const name = newOrg.trim();
    const domain = newDomain.trim() || `${name.toLowerCase().replace(/\s+/g, "")}.com`;
    if (!name) { toast({ title: "Enter organization name", variant: "destructive" }); return; }
    if (orgs.find(o => o.name.toLowerCase() === name.toLowerCase())) {
      toast({ title: "Already monitoring this organization", variant: "destructive" }); return;
    }
    const entry: OrgEntry = {
      id: crypto.randomUUID(),
      name, domain,
      addedAt: new Date().toISOString(),
      lastChecked: null,
      status: "monitoring",
      riskScore: 0,
      findings: [],
    };
    const next = [entry, ...orgs];
    save(next);
    setNewOrg(""); setNewDomain("");
    toast({ title: `Monitoring ${name}`, description: "Click Check Now to run initial scan" });
  };

  const checkOrg = useCallback(async (id: string) => {
    const org = orgs.find(o => o.id === id);
    if (!org) return;
    save(orgs.map(o => o.id === id ? { ...o, status: "checking" } : o));
    try {
      const settled = await Promise.allSettled([
        checkHIBP(org.domain),
        checkInternalFeed(org.name, org.domain),
        checkHudsonRock(org.domain),
        checkLiveAttackSurface(org.domain),  // Shodan + GreyNoise + URLhaus + ThreatFox + OTX + ransomware.live
        checkNewsMentions(org.name, org.domain), // Live Google News for org+threat keywords
      ]);
      const findings: OrgFinding[] = [];
      for (const s of settled) if (s.status === "fulfilled") findings.push(...s.value);
      const riskScore = calcRisk(findings);
      const status = riskScore >= 60 ? "alert" : riskScore >= 20 ? "alert" : findings.length > 0 ? "alert" : "clean";

      save(orgs.map(o => o.id === id
        ? { ...o, findings, riskScore, status, lastChecked: new Date().toISOString() }
        : o
      ));

      if (findings.length > 0) {
        setSummaryLoading(p => ({ ...p, [id]: true }));
        const summary = await generateOrgRiskSummary(org.name, findings);
        setAiSummary(p => ({ ...p, [id]: summary }));
        setSummaryLoading(p => ({ ...p, [id]: false }));
      }

      toast({
        title: findings.length > 0 ? `⚠ ${findings.length} findings for ${org.name}` : `✓ ${org.name} — no active threats`,
        description: riskScore >= 60 ? "Critical risk level — immediate action required" : undefined,
        variant: riskScore >= 60 ? "destructive" : "default",
      });
    } catch (e: any) {
      save(orgs.map(o => o.id === id ? { ...o, status: "monitoring" } : o));
      toast({ title: "Check failed", description: e.message, variant: "destructive" });
    }
  }, [orgs]);

  const removeOrg = (id: string) => {
    save(orgs.filter(o => o.id !== id));
    if (selected === id) setSelected(null);
  };

  const selectedOrg = orgs.find(o => o.id === selected);
  const statusIcon = (s: OrgEntry["status"]) => {
    if (s === "alert") return <AlertOctagon className="h-4 w-4 text-red-400" />;
    if (s === "clean") return <CheckCircle className="h-4 w-4 text-green-400" />;
    if (s === "checking") return <RefreshCw className="h-4 w-4 text-primary animate-spin" />;
    return <Eye className="h-4 w-4 text-muted-foreground" />;
  };

  const riskColor = (score: number) =>
    score >= 70 ? "text-red-400" : score >= 40 ? "text-orange-400" : score >= 15 ? "text-amber-400" : "text-green-400";

  return (
    <div className="container mx-auto px-4 py-8 max-w-6xl">
      {/* Header */}
      <div className="mb-6">
        <Badge variant="outline" className="mb-3 border-orange-500/40 bg-orange-500/10 text-orange-400 text-[11px]">
          <Zap className="mr-1.5 h-3 w-3" /> Continuous Monitoring
        </Badge>
        <h1 className="text-2xl font-bold tracking-tight flex items-center gap-2">
          <Building2 className="h-6 w-6 text-primary" /> Organization Threat Monitor
        </h1>
        <p className="text-sm text-muted-foreground mt-1">
          Track organizations across breach databases, threat feeds, stealer logs, and dark web mentions. Get alerted when a company appears in any intelligence source.
        </p>
      </div>

      {/* Add org */}
      <Card className="mb-6 border-border/50">
        <CardContent className="pt-4 pb-4">
          <div className="flex flex-wrap gap-2 items-end">
            <div className="flex-1 min-w-[180px]">
              <label className="text-xs text-muted-foreground mb-1 block">Organization Name</label>
              <Input placeholder="e.g. Micron, Adobe, Tesla" value={newOrg}
                onChange={e => setNewOrg(e.target.value)}
                onKeyDown={e => e.key === "Enter" && addOrg()} />
            </div>
            <div className="flex-1 min-w-[180px]">
              <label className="text-xs text-muted-foreground mb-1 block">Domain (optional)</label>
              <Input placeholder="e.g. micron.com" value={newDomain}
                onChange={e => setNewDomain(e.target.value)}
                onKeyDown={e => e.key === "Enter" && addOrg()} />
            </div>
            <Button onClick={addOrg} className="gap-1.5 shrink-0">
              <Plus className="h-4 w-4" /> Add to Monitor
            </Button>
          </div>
          <p className="text-[11px] text-muted-foreground mt-2">
            Checks: HIBP breach database · Internal threat feed · Hudson Rock stealer logs · AI risk correlation
          </p>
        </CardContent>
      </Card>

      {orgs.length === 0 ? (
        <Card className="border-dashed border-border/40">
          <CardContent className="py-16 text-center">
            <Building2 className="h-10 w-10 text-muted-foreground/40 mx-auto mb-3" />
            <p className="text-muted-foreground text-sm">No organizations being monitored</p>
            <p className="text-muted-foreground/60 text-xs mt-1">Add a company name above to start monitoring</p>
            <div className="flex gap-2 justify-center mt-4">
              {["Micron", "Adobe", "Microsoft"].map(n => (
                <Button key={n} variant="outline" size="sm" className="text-xs" onClick={() => { setNewOrg(n); setNewDomain(`${n.toLowerCase()}.com`); }}>
                  + {n}
                </Button>
              ))}
            </div>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
          {/* Org list */}
          <div className="space-y-3">
            {orgs.map(org => (
              <Card key={org.id}
                className={`border cursor-pointer transition-all hover:border-primary/40 ${selected === org.id ? "border-primary/50 bg-primary/5" : "border-border/40"}`}
                onClick={() => setSelected(selected === org.id ? null : org.id)}>
                <CardContent className="pt-3 pb-3 px-4">
                  <div className="flex items-start justify-between gap-2">
                    <div className="flex items-center gap-2 min-w-0">
                      {statusIcon(org.status)}
                      <div className="min-w-0">
                        <div className="font-semibold text-sm truncate">{org.name}</div>
                        <div className="text-[11px] text-muted-foreground truncate">{org.domain}</div>
                      </div>
                    </div>
                    <button onClick={e => { e.stopPropagation(); removeOrg(org.id); }}
                      className="text-muted-foreground hover:text-destructive transition-colors shrink-0">
                      <Trash2 className="h-3.5 w-3.5" />
                    </button>
                  </div>

                  <div className="flex items-center gap-2 mt-2.5">
                    <div className="flex-1 h-1.5 rounded-full bg-muted overflow-hidden">
                      <div className={`h-full rounded-full ${org.riskScore >= 70 ? "bg-red-500" : org.riskScore >= 40 ? "bg-orange-500" : org.riskScore >= 15 ? "bg-amber-500" : "bg-green-500"}`}
                        style={{ width: `${org.riskScore}%` }} />
                    </div>
                    <span className={`text-xs font-bold tabular-nums ${riskColor(org.riskScore)}`}>{org.riskScore}</span>
                  </div>

                  <div className="flex items-center justify-between mt-2">
                    <span className="text-[10px] text-muted-foreground">
                      {org.findings.length} findings · {org.lastChecked ? new Date(org.lastChecked).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) : "not checked"}
                    </span>
                    <Button variant="ghost" size="sm" className="h-6 text-[11px] gap-1 px-2"
                      disabled={org.status === "checking"}
                      onClick={e => { e.stopPropagation(); checkOrg(org.id); }}>
                      {org.status === "checking" ? <RefreshCw className="h-3 w-3 animate-spin" /> : <RefreshCw className="h-3 w-3" />}
                      {org.status === "checking" ? "Checking…" : "Check Now"}
                    </Button>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>

          {/* Detail panel */}
          <div className="lg:col-span-2">
            {selectedOrg ? (
              <div className="space-y-4">
                {/* Risk header */}
                <Card className={`border ${selectedOrg.riskScore >= 70 ? "border-red-500/40 bg-red-500/5" : selectedOrg.riskScore >= 30 ? "border-orange-500/40 bg-orange-500/5" : "border-green-500/40 bg-green-500/5"}`}>
                  <CardContent className="pt-4 pb-4 px-5">
                    <div className="flex items-center justify-between flex-wrap gap-3">
                      <div>
                        <div className="flex items-center gap-2">
                          <Building2 className="h-5 w-5 text-muted-foreground" />
                          <span className="font-bold text-lg">{selectedOrg.name}</span>
                          <Badge variant="outline" className="text-[10px] font-mono">{selectedOrg.domain}</Badge>
                          <CopyBtn value={selectedOrg.domain} />
                        </div>
                        <div className="text-xs text-muted-foreground mt-0.5">
                          Last checked: {selectedOrg.lastChecked ? new Date(selectedOrg.lastChecked).toLocaleString() : "Never"}
                        </div>
                      </div>
                      <div className="text-right">
                        <div className={`text-4xl font-black ${riskColor(selectedOrg.riskScore)}`}>{selectedOrg.riskScore}</div>
                        <div className="text-xs text-muted-foreground">Risk Score / 100</div>
                      </div>
                    </div>
                  </CardContent>
                </Card>

                {/* AI Summary */}
                {(aiSummary[selectedOrg.id] || summaryLoading[selectedOrg.id]) && (
                  <Card className="border-primary/25 bg-primary/5">
                    <CardContent className="pt-4 pb-4 px-5">
                      <div className="flex items-center gap-1.5 mb-2 text-xs font-bold text-primary uppercase tracking-wider">
                        <Zap className="h-3.5 w-3.5" /> AI Risk Assessment
                      </div>
                      {summaryLoading[selectedOrg.id]
                        ? <div className="flex items-center gap-2 text-sm text-muted-foreground"><RefreshCw className="h-3.5 w-3.5 animate-spin" /> Generating AI summary…</div>
                        : <p className="text-sm text-foreground/90 leading-relaxed">{aiSummary[selectedOrg.id]}</p>
                      }
                    </CardContent>
                  </Card>
                )}

                {/* Findings */}
                {selectedOrg.findings.length === 0 ? (
                  <Card className="border-border/40">
                    <CardContent className="py-10 text-center">
                      {selectedOrg.lastChecked
                        ? <><CheckCircle className="h-8 w-8 text-green-400 mx-auto mb-2" /><p className="text-sm text-muted-foreground">No threats found in last scan</p></>
                        : <><Eye className="h-8 w-8 text-muted-foreground/40 mx-auto mb-2" /><p className="text-sm text-muted-foreground">Click "Check Now" to run intelligence scan</p></>
                      }
                    </CardContent>
                  </Card>
                ) : (
                  <Card className="border-border/40">
                    <CardHeader className="pb-2 pt-4 px-4">
                      <div className="flex items-center justify-between flex-wrap gap-2">
                        <CardTitle className="text-sm flex items-center gap-1.5">
                          <AlertTriangle className="h-4 w-4 text-amber-400" />
                          Intelligence Findings ({selectedOrg.findings.length})
                        </CardTitle>
                        <div className="flex items-center gap-1.5">
                          <Button variant="outline" size="sm" className="h-7 text-[11px] gap-1 px-2.5"
                            onClick={() => downloadJSON(selectedOrg)}>
                            <FileJson className="h-3 w-3" /> JSON
                          </Button>
                          <Button variant="outline" size="sm" className="h-7 text-[11px] gap-1 px-2.5"
                            onClick={() => downloadCSV(selectedOrg)}>
                            <FileText className="h-3 w-3" /> CSV
                          </Button>
                        </div>
                      </div>
                    </CardHeader>
                    <CardContent className="px-4 pb-4">
                      <div className="space-y-3 max-h-[520px] overflow-y-auto pr-1">
                        {selectedOrg.findings.map((f, i) => (
                          <FindingCard key={i} f={f} />
                        ))}
                      </div>
                    </CardContent>
                  </Card>
                )}
              </div>
            ) : (
              <Card className="border-dashed border-border/40 h-full">
                <CardContent className="flex items-center justify-center h-full min-h-48">
                  <div className="text-center">
                    <Building2 className="h-8 w-8 text-muted-foreground/30 mx-auto mb-2" />
                    <p className="text-sm text-muted-foreground">Select an organization to view findings</p>
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
